// ---- downloads ----
// The temporary link must outlive the click: revoking it at once cancels the download in some browsers.
download(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.style.display = "none";
  document.body.appendChild(a); a.click();
  setTimeout(() => { a.remove(); URL.revokeObjectURL(url); }, 10000);
},
// a readable reason from a failed response (the server's detail, else the status)
async errorText(res, fallback) {
  try {
    const d = await res.json();
    if (typeof d.detail === "string") return fallback + ": " + d.detail;
  } catch (e) {}
  return fallback + " (" + res.status + ")";
},

